head.script:
///////// 1. 변수 및 선언 영역 /////////
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        tab_Main.setSelectedTabIndex(1);
        $c.bns.BnsPanelToGroupBox(panel_Top_1);
        $c.bns.BnsPanelToGroupBox(panel_Top_2);
        $c.bns.BnsPanelToGroupBox(panel_Top_3);
        $c.bns.BnsPanelToGroupBox(panel_Top_4);

        // fn_initSearchDate(edt_SDate, edt_EDate);                       // 신청일 기간

        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        await scwin.getDate();
        edt_Ji_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ji_EDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ba_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ba_EDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ja_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ja_EDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Pl_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_Ji_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Ji_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Ba_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Ba_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Ja_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Ja_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
        edt_Pl_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));

        // fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25500.onpageload" });
    }
};

/**
