/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : btn_Search > onclick
         * 설명      : 조회버튼 클릭
         ***********************************************/
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25500.btn_Search_onclick" });
    }
};

