/**
 * @method
 * @name rdo_Ja_Trem_onclick
 * @description rdo_Ja_Trem 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_Ja_Trem_onclick = function() {
    try {
        /**********************************************
         * 함수명   : rdo_Ja_Trem > onclick
         * 설명      : rdo_Ja_Trem 기간 선택
         ***********************************************/
        const vs_Ja_Term = rdo_Ja_Trem.getValue();
        if (vs_Ja_Term === "D") {
            edt_Ja_SDate.setValue(edt_Ja_EDate.getValue());
        } else if (vs_Ja_Term === "M") {
            let vsYYYYMMDD = edt_Ja_EDate.getValue();
            let yyyy = vsYYYYMMDD.substring(0, 4);
            let mm = vsYYYYMMDD.substring(4, 6);
            let dd = vsYYYYMMDD.substring(6, 8);
            edt_Ja_SDate.setValue($c.ut.cGetMinusMonth(yyyy, mm, dd, 1));
        } else if (vs_Ja_Term === "Y") {
            edt_Ja_SDate.setValue($c.ut.cGetMinusYear(edt_Ja_EDate.getValue(), 1));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25500.rdo_Ja_Trem_onclick" });
    }
};

/**
 * @method
 * @name rdo_Ja_Gb_onclick
 * @description rdo_Ja_Gb 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_Ja_Gb_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : rdo_Ja_Gb > onclick
         * 설명      : rdo_Ja_Gb 클릭
         ***********************************************/
        let vs_Ja_Gb = rdo_Ja_Gb.getValue();
        if (vs_Ja_Gb === "S") {
            $c.cm.setColumnProp(grd_List3, "MM_12", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_60_84", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_84_120", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_120_180", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_180_240", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_240_360", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_ETC", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_360_600", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_6", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_6_12", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_60_120", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_120_UP", "Show", "false");
        } else if (vs_Ja_Gb === "L") {
            $c.cm.setColumnProp(grd_List3, "MM_360_600", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_12", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_60_84", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_84_120", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_120_180", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_180_240", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_240_360", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_ETC", "Show", "false");
            $c.cm.setColumnProp(grd_List3, "MM_6", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_6_12", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_60_120", "Show", "true");
            $c.cm.setColumnProp(grd_List3, "MM_120_UP", "Show", "true");
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25500.rdo_Ja_Gb_onclick" });
    }
};

/**
 * @method
 * @name rdo_Ji_Trem_onclick
 * @description rdo_Ji_Trem 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_Ji_Trem_onclick = function() {
    try {
        /**********************************************
         * 함수명   : vs_Ji_Term > onclick
         * 설명      : vs_Ji_Term 기간 선택
         ***********************************************/
        const vs_Ji_Term = rdo_Ji_Trem.getValue();
        if (vs_Ji_Term === "D") {
            edt_Ji_SDate.setValue(edt_Ji_EDate.getValue());
        } else if (vs_Ji_Term === "M") {
            let vsYYYYMMDD = edt_Ji_EDate.getValue();
            let yyyy = vsYYYYMMDD.substring(0, 4);
            let mm = vsYYYYMMDD.substring(4, 6);
            let dd = vsYYYYMMDD.substring(6, 8);
            edt_Ji_SDate.setValue($c.ut.cGetMinusMonth(yyyy, mm, dd, 1));
        } else if (vs_Ji_Term === "Y") {
            edt_Ji_SDate.setValue($c.ut.cGetMinusYear(edt_Ji_EDate.getValue(), 1));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25500.rdo_Ji_Trem_onclick" });
    }
};

/**
 * @method
 * @name rdo_Ba_Trem_onclick
 * @description rdo_Ba_Trem 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_Ba_Trem_onclick = function() {
    try {
        /**********************************************
         * 함수명   : vs_Ba_Term > onclick
         * 설명      : vs_Ba_Term 기간 선택
         ***********************************************/
        const vs_Ba_Term = rdo_Ba_Trem.getValue();
        if (vs_Ba_Term === "D") {
            edt_Ba_SDate.setValue(edt_Ba_EDate.getValue());
        } else if (vs_Ba_Term === "M") {
            let vsYYYYMMDD = edt_Ba_EDate.getValue();
            let yyyy = vsYYYYMMDD.substring(0, 4);
            let mm = vsYYYYMMDD.substring(4, 6);
            let dd = vsYYYYMMDD.substring(6, 8);
            edt_Ba_SDate.setValue($c.ut.cGetMinusMonth(yyyy, mm, dd, 1));
        } else if (vs_Ba_Term === "Y") {
            edt_Ba_SDate.setValue($c.ut.cGetMinusYear(edt_Ba_EDate.getValue(), 1));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25500.rdo_Ba_Trem_onclick" });
    }
};

