///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();

    // 지표종목별
    if (vsTabSel === "1") {
        await scwin.search1();
        // 발행만기별

    } else if (vsTabSel === "2") {
        await scwin.search2();
        // 잔존만기별

    } else if (vsTabSel === "3") {
        await scwin.search3();
        // 개별종목별

    } else if (vsTabSel === "4") {
        await scwin.search4();
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();
    let voDtsList = null;
    let voGrid = null;
    let excelSheet = '';

    // 전체조회
    if (vsTabSel === "1") {
        excelSheet = '지표종목별';
        voDtsList = dts_List1;
        voGrid = grd_List1;
        // 개별종목조회

    } else if (vsTabSel === "2") {
        excelSheet = '발행만기별';
        voDtsList = dts_List2;
        voGrid = grd_List2;
        // 일괄상장종목조회

    } else if (vsTabSel === "3") {
        excelSheet = '잔존만기별';
        voDtsList = dts_List3;
        voGrid = grd_List3;
        // 일괄상장종목조회

    } else if (vsTabSel === "4") {
        excelSheet = '개별종목별';
        voDtsList = dts_List4;
        voGrid = grd_List4;
    }
    if (voDtsList.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS25500.xml", SCREN_PROCS_TP_CD_07);
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_국고채권 상장잔액.xls";
        voGrid.GridToExcel(excelSheet, "", "8");
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
